import type { VerificationAttributes } from '@celo/buy-keystore';
/**
 * Self.xyz `endpointType` from the SelfAppBuilder config.
 *
 *  - `https` / `staging_https` → off-chain backend verifier; `endpoint` is the HTTPS URL
 *  - `celo` / `staging_celo`   → on-chain hub verifier;   `endpoint` is the contract address
 *
 * Mismatching these causes the Self mobile app to reject with "Invalid 'to' address".
 */
export type SelfEndpointType = 'https' | 'staging_https' | 'celo' | 'staging_celo';
/** @deprecated Renamed to `SelfEndpointType`. Kept temporarily for back-compat. */
export type SelfNetwork = SelfEndpointType;
/**
 * High-level KYC requirements requested from the user. Maps 1:1 onto Self.xyz
 * `disclosures` + the SelfBackendVerifier config. Kept tiny on purpose — we
 * surface only the attributes the bug-bounty / x402 challenge space needs.
 */
export type SoftKycRequirements = {
    minimumAge?: number;
    excludedCountries?: string[];
    /** Require non-OFAC. */
    notOfac?: boolean;
    /** Request the prover disclose their nationality (ISO-3 code). */
    discloseNationality?: boolean;
    /** Request the prover disclose their gender. */
    discloseGender?: boolean;
};
export type VerificationRequest = {
    /** Stable scope ID — usually a fixed string per app, e.g. "buy" or "buy-demo". */
    scope: string;
    /** Public callback URL that Self mobile app POSTs the proof to. */
    endpoint: string;
    /** Whether to accept the mock-passport flow (staging only). */
    /**
     * Which Self hub to verify against: false = mainnet (real passports),
     * true = staging (mock passports), `'either'` = try both.
     *
     * `'either'` exists so one deployment can serve testers using mock
     * passports alongside real users, which a single verifier cannot do —
     * see `verifyProof`.
     */
    mockPassport: boolean | 'either';
    /** EVM address (hex) the proof is bound to. */
    userId: string;
    /** Requested disclosures + thresholds. */
    requirements: SoftKycRequirements;
    /**
     * Free-form context echoed back in the proof.
     *
     * NOT merely diagnostic, despite how it reads: it is a slice of
     * `userContextData`, and the circuit commits to that value's sha256 as a
     * public signal. Whatever the verifier puts here comes back provably
     * unaltered, which is what lets a receiver serving many unknown callers bind
     * a proof to the session that asked for it.
     */
    userDefinedData?: string;
    /**
     * Self.xyz endpointType — picks staging/production AND on-chain/off-chain.
     * For buy's HTTPS proof receiver this is `staging_https` or `https`.
     */
    endpointType: SelfEndpointType;
    /** Human-readable app name shown in the Self mobile app. */
    appName: string;
};
/** Result returned from a successful proof verification. */
export type VerificationResult = {
    ok: true;
    attributes: VerificationAttributes;
    proofHash: string;
    /** Address the proof was bound to (Self's `userData.userIdentifier`). */
    userIdentifier?: string;
    /** Per-user per-scope unique value from the proof. */
    nullifier?: string;
    /**
     * The request's `userDefinedData`, decoded back to the string that was sent.
     *
     * Undefined when absent or not valid UTF-8 — never a lossy approximation, so
     * two different proofs can never decode onto one value. Bound to the proof
     * via the committed `userContextData` hash; see the note on
     * `VerificationRequest.userDefinedData`.
     */
    userDefinedData?: string;
    /**
     * The same value exactly as the verifier returned it: the hex tail of
     * `userContextData`, undecoded. Compare THIS when the value identifies
     * something — it is the bytes the circuit committed to, with no decode step
     * to disagree about.
     */
    userDefinedDataHex?: string;
    /**
     * Which Self hub validated this proof: true = staging (mock passports),
     * false = mainnet (real ones).
     *
     * Only interesting when the request said `'either'`, but always set, because
     * the attestation must record the matching `endpointType` — re-verification
     * picks its hub from that, and a mismatch fails with `InvalidRoot` on a proof
     * that is perfectly valid.
     */
    usedMockPassport?: boolean;
};
export type VerificationFailure = {
    ok: false;
    reason: string;
};
export type { VerificationAttributes } from '@celo/buy-keystore';
